const items = $input.all();
const results = [];
for (const item of items) {
  const text = item.json.message?.text || '';
  const match = text.match(/^(.+?)\s+(\d+)$/);
  if (match) {
    results.push({
      json: {
        category: match[1].trim(),
        amount: parseInt(match[2]),
        userId: item.json.message?.from?.id,
        username: item.json.message?.from?.username || 'unknown',
        chatId: item.json.message?.chat?.id,
        timestamp: new Date().toISOString(),
        date: new Date().toISOString().split('T')[0]
      }
    });
  } else {
    results.push({
      json: {
        error: true,
        chatId: item.json.message?.chat?.id,
        text: text
      }
    });
  }
}
return results;

const items = $input.all();
const expenses = items.map(i => i.json);
const today = new Date().toISOString().split('T')[0];
const todayExpenses = expenses.filter(e => e.date === today);
const todayTotal = todayExpenses.reduce((sum, e) => sum + parseInt(e.amount || 0), 0);
const monthTotal = expenses.reduce((sum, e) => sum + parseInt(e.amount || 0), 0);
return [{
  json: {
    todayTotal,
    monthTotal,
    todayCount: todayExpenses.length,
    totalCount: expenses.length
  }
}];
